import React, { useContext, useState, Suspense, startTranslation, useEffect} from "react";
import { AuthContext } from "../context";
import style from "../styles/Light/Main.module.css"
import MyButton from "../UI/components/buttons/MyButton";
import MyInput from "../UI/components/input/MyInput";
import 'bootstrap/dist/css/bootstrap.min.css';
import { useTranslation } from 'react-i18next';
import { useHistory } from 'react-router-dom';


const MainLight = () => {
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState(null);
    const [accessToken, setAccessToken] = useState(localStorage.getItem('accessToken'));
    const [requestData, setRequestData] = useState({prompt: ''});
    const handlePromptChange = (event) => {
        const prompt = event.target.value;
        setRequestData({ ...requestData, prompt });
    };

    // Функция обновления access токена
  const refreshAccessToken = async () => {
    try {
      const refreshToken = localStorage.getItem('refreshToken');
      if (!refreshToken) {
        throw new Error('Refresh token not found');
      }

      const response = await fetch('http://localhost:8000/api/users/refresh/', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ refresh: refreshToken }),
      });

      if (!response.ok) {
        throw new Error('Failed to refresh token');
      }

      const data = await response.json();
      const newAccessToken = data.access;

      // Обновляем токен в локальном хранилище и состоянии
      localStorage.setItem('accessToken', newAccessToken);
      setAccessToken(newAccessToken);
    } catch (err) {
      console.error('Error refreshing token:', err);
      setError('Ошибка обновления токена. Пожалуйста, войдите снова.');
      // Здесь можно добавить логику выхода из аккаунта
    }
  };

  // Запускаем таймер обновления токена при загрузке компонента
  useEffect(() => {
    // Обновляем токен сразу при загрузке (по желанию)
    refreshAccessToken();

    const intervalId = setInterval(() => {
      refreshAccessToken();
    }, 5 * 60 * 1000); // 5 минут

    return () => clearInterval(intervalId); // Очистка таймера при размонтировании
  }, []);

    const handleSubmit = async (event) => {
        event.preventDefault();
        setIsLoading(true);
        setError(null);
      
        try {
          const userId = getUserIdFromToken();
          if (!accessToken) {
            throw new Error('JWT token not found');
          }
      
          // Отправляем POST-запрос
          const response = await fetch('http://localhost:8000/api/requests/', {
            method: 'POST',
            headers: {
              'Content-Type': 'application/json',
              'Authorization': `Bearer ${accessToken}`,
            },
            body: JSON.stringify({
              user_id: userId,
              prompt: requestData.prompt,
            }),
          });
      
          if (response.status === 201) {
            const data = await response.json();
            console.log(data)
            const operationId = data.operationID;
            console.log(operationId)
      
            // Функция для повторного запроса изображения с задержкой
            const fetchImageWithRetry = async (retries = 5, delay = 2000) => {
              for (let i = 0; i < retries; i++) {
                const imageResponse = await fetch(
                  `http://localhost:8000/api/getimage/?operation_id=${operationId}&user_id=${userId}`,
                  {
                    headers: {
                      'Authorization': `Bearer ${accessToken}`,
                    },
                  }
                );
      
                if (imageResponse.ok) {
                  const blob = await imageResponse.blob();
                  const imageUrl = URL.createObjectURL(blob);
                  setImageSrc(imageUrl);
                  return; // Успешно получили изображение, выходим из функции
                } else if (imageResponse.status === 404) {
                  // Изображение ещё не готово, ждём и повторяем попытку
                  await new Promise(res => setTimeout(res, delay));
                } else {
                  // Ошибка, прерываем попытки
                  setError('Ошибка при получении изображения');
                  return;
                }
              }
              setError('Изображение не появилось в течение ожидания');
            };
      
            // Запускаем получение изображения с повторными попытками
            await fetchImageWithRetry();
      
          } else {
            setError(`Ошибка при отправке запроса: статус ${response.status}`);
          }
        } catch (error) {
          setError(error.message);
        } finally {
          setIsLoading(false);
        }
      };
      
    const [imageSrc, setImageSrc] = useState(null);      
    function getUserIdFromToken() {
        const token = localStorage.getItem('accessToken'); // Получаем токен из localStorage
        if (!token) {
            throw new Error('JWT token not found in localStorage');
        }
    
        // Декодируем токен (предполагаем, что он закодирован в формате base64)
        const payload = token.split('.')[1]; // Берем среднюю часть токена
        const decodedPayload = JSON.parse(atob(payload)); // Декодируем base64 и парсим JSON
        console.log(decodedPayload)
        return decodedPayload.user_id; // Предполагаем, что ID пользователя хранится в поле userId
    }
    
    // Функция для отправки запроса на сервер
    // переход между страницами
    const history = useHistory();
    const handleRedirectToLogin = () => {
        history.push('/login');
    };
    const returnToLogin = () => {
        history.push('/login');
    };
    const returnOurTeam = () => {
        history.push('/ourteam');
    };
    const { t, i18n } = useTranslation('translation');
    return (
        <div>
            <Suspense fallback={<div>Loading...</div>}>
                {startTranslation}
            </Suspense>
            {/** контейнер страницы */}
            <div className={style.LoginPage}>
                {/** заголовок*/}
                <div className={style.Header}>
                    <a
                        onClick={returnToLogin}
                        className={style.HeaderLink}
                    >
                        Генератор Гена
                    </a>
                </div>
                <div className="container-fluid">
                    <div className={style.MainPage}>
                        <div className="row">
                            <div className={'col-lg-2'}></div>
                            <div className={`col-lg-5 text-center`}>
                                <div className={style.Info}>
                                    <h2>Генератор Гена</h2>
                                    <h3 className={style.text}>Сервис для генерации изображения по промпту</h3>
                                    <div className={style.Link}>
                                        <a className={style.text}>App Store</a>
                                        <a className={style.text}>Google Play</a>
                                        <a className={style.text}>Linux</a>
                                        <a className={style.text}>Windows</a>
                                    </div>
                                </div>
                                {imageSrc && <img src={imageSrc} alt="Полученное изображение" />}
                            </div>
                            <div className={`col-lg-3`}>
                                <div className={style.MainForm}>
                                    <form className={style.form} >
                                        <h1>Введите промпт</h1>
                                        <MyInput
                                            style={{ margin: '0px', marginTop: '8%' }}
                                            type="text"
                                            placeholder='Введите имя пользователя'
                                            onChange={handlePromptChange}
                                        />
                                        <MyButton
                                            style={{ backgroundColor: '#1F5CB6', color: '#ffffff', margin: '0px', marginTop: '8%' }}
                                            onClick={handleSubmit}
                                        >
                                            Продолжить
                                        </MyButton>
                                    </form>
                                </div>
                                <div className={style.QR} >
                                    <div className={style.textQr}>
                                        <h5 className={style.text}>Да итоговый дизайн отличается от дизайн макета</h5>
                                        <h6 className={style.text}>ИЗВИНИТЕСЬ</h6>
                                        <a className={style.more}>фронтендер не умеет красить кнопки</a>
                                    </div>
                                </div>
                            </div>
                            {/** ссылки внизу страницы */}
                            <div className={style.Bottom}>
                                <h4>Гена © 2025</h4>
                                <a
                                    className={style.text}
                                    onClick={returnOurTeam}
                                    style={{ marginRight: "15%" }}
                                >
                                    Github
                                </a>
                                <a
                                    onClick={() => i18n.changeLanguage('en')}
                                    className={style.text}
                                >
                                    English
                                </a>
                                <a
                                    onClick={() => i18n.changeLanguage('ru')}
                                    className={style.text}
                                    style={{ marginRight: "10%" }}
                                >
                                    Русский
                                </a>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};
export default MainLight;
